// Get the structured report generated by the AI Agent
let report = $json.output;

// Safety check in case the AI output is returned as a JSON string
if (typeof report === 'string') {
  let cleanStr = report.trim();
  if (cleanStr.startsWith('```')) {
    cleanStr = cleanStr.replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
  }
  try {
    report = JSON.parse(cleanStr);
  } catch (error) {
    report = {};
  }
}

const ctx = $('11. Profession Prompt Adapter').first().json;
const profession = ctx.profession || 'professor_teacher';
const userName = ctx.userName || 'InboxIQ Member';
const userTimezone = ctx.timezone || 'Asia/Kolkata';

// Helper functions
const escapeHtml = (value) => {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const safeArray = (value) => {
  return Array.isArray(value) ? value : [];
};

const formatDate = (date) => {
  if (!date) return '';
  const d = new Date(date);
  if (isNaN(d.getTime())) {
    return escapeHtml(date);
  }
  return d.toLocaleString('en-IN', {
    dateStyle: 'medium',
    timeStyle: 'short',
    timeZone: userTimezone
  });
};

// Data from AI Agent
const reportDate = report.reportDate || ctx.reportDate;
const totalEmails = typeof report.totalEmails === 'number' ? report.totalEmails : ctx.totalEmails;

const importantEmails = safeArray(report.importantEmails);
const urgentEmails = safeArray(report.urgentEmails);
const repliedEmails = safeArray(report.repliedEmails);
const otherEmails = safeArray(report.otherEmails);
const actionItems = safeArray(report.actionItems);

const overallSummary =
  report.overallSummary || (totalEmails === 0 ? 'No new emails received during this 24-hour reporting window.' : 'Email intelligence report synthesized by InboxIQ.');

// Dynamic profession badge & gradient
let badgeTitle = 'Faculty Intelligence';
let headerGradient = 'linear-gradient(135deg, #111827 0%, #1f2937 100%)';
if (profession === 'student') {
  badgeTitle = 'Student Academic Pulse';
  headerGradient = 'linear-gradient(135deg, #064e3b 0%, #047857 100%)';
} else if (profession === 'others') {
  badgeTitle = 'Executive Intelligence';
  headerGradient = 'linear-gradient(135deg, #18181b 0%, #27272a 100%)';
}

// Create email cards
function createEmailCards(emails, type) {
  if (emails.length === 0) {
    return '<div class="empty">None</div>';
  }

  return emails.map(email => {
    const sender = escapeHtml(email.sender || 'Unknown sender');
    const subject = escapeHtml(email.subject || 'No subject');
    const dateTime = formatDate(email.dateTime);
    const reason = escapeHtml(
      email.reason ||
      email.summary ||
      email.context ||
      'No additional information available.'
    );
    const action = escapeHtml(
      email.action ||
      email.requiredAction ||
      email.status ||
      ''
    );

    return `
      <div class="email-card ${type}">
        <div class="email-header">
          <div class="email-main-info">
            <div class="sender">${sender}</div>
            <div class="subject">${subject}</div>
          </div>
          <div class="datetime">${dateTime}</div>
        </div>
        <div class="email-content">
          <div class="label">Why it matters</div>
          <div class="text">${reason}</div>
          ${action ? `<div class="label">Status / Required Action</div><div class="text">${action}</div>` : ''}
        </div>
      </div>
    `;
  }).join('');
}

// Create action items
function createActionItems(items) {
  if (items.length === 0) {
    return '<div class="empty">None</div>';
  }
  return `
    <ul class="action-list">
      ${items.map(item => `<li>${escapeHtml(item)}</li>`).join('')}
    </ul>
  `;
}

// Generate the complete professional report
const html = `<!DOCTYPE html>
